import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining characteristics designed to match specific ELA features.

    This function features a weighted sum of Levy, Rastrigin, and a skewed power function to control various ELA aspects.

    Formula:
    f(x) = w_levy * Levy(x) + w_rastrigin * Rastrigin(x) + w_skew * SkewedPower(x)

    where:
    - Levy(x) = sin^2(pi*w1) + sum{ (wi-1)^2 * (1 + 10*sin^2(pi*wi)) } + (wn-1)^2 * (1 + sin^2(2*pi*wn))
      with wi = 1 + (xi-1)/4
    - Rastrigin(x) = 10*N + sum{ xi^2 - 10*cos(2*pi*xi) }
    - SkewedPower(x) = sum{ x_i^(2 + skew_factor*indicator(x_i)) }
      with indicator(x_i) = 1 if x_i > 0 else 0
    """
    w_levy = 0.1  # Adjust for ruggedness and linearity
    w_rastrigin = 0.4  # Adjust for ruggedness, multimodality, nn-nb ratio
    w_skew = 0.5  # Adjust for skewness

    def levy(x):
        y = 1 + (x - 1) / 4
        term1 = np.sin(np.pi * y[0])**2
        term2 = np.sum((y[:-1] - 1)**2 * (1 + 10 * np.sin(np.pi * y[:-1] + 1e-9)**2))  # Adding a small value to prevent NaN
        term3 = (y[-1] - 1)**2 * (1 + np.sin(2 * np.pi * y[-1])**2)
        return term1 + term2 + term3

    def rastrigin(x):
        return 10 * len(x) + np.sum(x**2 - 10 * np.cos(2 * np.pi * x))

    def skewed_power(x):
        skew_factor = 0.1
        indicator = np.where(x > 0, 1, 0)
        return np.sum(x**(2 + skew_factor * indicator))

    return w_levy * levy(x) + w_rastrigin * rastrigin(x) + w_skew * skewed_power(x)
